rite || selectedNode.config.columns >= 20" @click="insertTableColumnAt(selectedNode, true)">{{ t('Column after') }}</button><button type="button" class="btn btn-sm btn-outline-danger" :disabled="!canWrite || selectedNode.config.columns <= 1" @click="deleteSelectedTableColumn(selectedNode)">{{ t('Delete column') }}</button></div><label class="workflow-check-row"><input type="checkbox" v-model="selectedNode.config.header" :disabled="!canWrite" @change="markDirty"><span>{{ t('Style first row as header') }}</span></label><div class="workflow-inspector-grid workflow-inspector-grid--two"><div><label for="workflow-table-font-size" class="form-label">{{ t('Font size') }}</label><input id="workflow-table-font-size" v-model.number="selectedNode.config.fontSize" class="form-control" type="number" min="10" max="32" step="1" :readonly="!canWrite" @focus="beginInspectorEdit" @input="markDirty"></div><div><label for="workflow-table-align" class="form-label">{{ t('Alignment') }}</label><select id="workflow-table-align" v-model="selectedNode.config.align" class="form-select" :disabled="!canWrite" @change="markDirty"><option value="left">{{ t('Left') }}</option><option value="center">{{ t('Center') }}</option><option value="right">{{ t('Right') }}</option></select></div></div><div class="workflow-color-grid"><label>{{ t('Text') }}<input v-model="selectedNode.config.textColor" type="color" :disabled="!canWrite" @focus="beginInspectorEdit" @input="markDirty"></label><label>{{ t('Background') }}<input v-model="selectedNode.config.background" type="color" :disabled="!canWrite" @focus="beginInspectorEdit" @input="markDirty"></label><label>{{ t('Header') }}<input v-model="selectedNode.config.headerBackground" type="color" :disabled="!canWrite" @focus="beginInspectorEdit" @input="markDirty"></label><label>{{ t('Border') }}<input v-model="selectedNode.config.borderColor" type="color" :disabled="!canWrite" @focus="beginInspectorEdit" @input="markDirty"></label></div><details class="workflow-size-details"><summary>{{ t('Column and row sizes') }}</summary><div class="workflow-size-list"><label v-for="(width, index) in selectedNode.config.columnWidths" :key="`workflow-column-width-${selectedNode.id}-${index}`">{{ t('Column') }} @{{ index + 1 }}<input class="form-control form-control-sm" type="number" min="60" max="600" step="1" :value="width" :readonly="!canWrite" @change="resizeTableNumber(selectedNode, 'column', index, $event.target.value)"></label><label v-for="(height, index) in selectedNode.config.rowHeights" :key="`workflow-row-height-${selectedNode.id}-${index}`">{{ t('Row') }} @{{ index + 1 }}<input class="form-control form-control-sm" type="number" min="28" max="240" step="1" :value="height" :readonly="!canWrite" @change="resizeTableNumber(selectedNode, 'row', index, $event.target.value)"></label></div></details></div>
                    <div v-if="selectedNode.type === 'icon'" class="workflow-inspector-section"><h3>{{ t('Icon settings') }}</h3><button type="button" class="workflow-icon-picker-trigger" :disabled="!canWrite" @click="openIconPicker(selectedNode)"><span class="workflow-icon-picker-trigger__preview"><i :class="safeIconClass(selectedNode.config.iconClass)" aria-hidden="true"></i></span><span><strong>@{{ selectedNode.config.iconClass }}</strong><small>{{ t('Choose from local Font Awesome') }}</small></span><i class="fas fa-chevron-right ms-auto" aria-hidden="true"></i></button><div class="workflow-inspector-grid workflow-inspector-grid--two"><div><label for="workflow-icon-size" class="form-label">{{ t('Icon size') }}</label><input id="workflow-icon-size" v-model.number="selectedNode.config.size" class="form-control" type="number" min="12" max="256" step="1" :readonly="!canWrite" @focus="beginInspectorEdit" @input="markDirty"></div><div><label for="workflow-icon-color" class="form-label">{{ t('Color') }}</label><input id="workflow-icon-color" v-model="selectedNode.config.color" class="form-control form-control-color w-100" type="color" :disabled="!canWrite" @focus="beginInspectorEdit" @input="markDirty"></div><div><label for="workflow-icon-width" class="form-label">{{ t('Width') }}</label><input id="workflow-icon-width" v-model.number="selectedNode.config.width" class="form-control" type="number" min="80" max="1000" step="1" :readonly="!canWrite" @focus="beginInspectorEdit" @input="markDirty"></div><div><label for="workflow-icon-height" class="form-label">{{ t('Height') }}</label><input id="workflow-icon-height" v-model.number="selectedNode.config.height" class="form-control" type="number" min="80" max="1000" step="1" :readonly="!canWrite" @focus="beginInspectorEdit" @input="markDirty"></div></div></div>
                    <div v-if="selectedNode.type === 'icon-list'" class="workflow-inspector-section"><h3>{{ t('Icon List settings') }}</h3><div class="workflow-icon-list-settings"><div v-for="(item, index) in selectedNode.config.items" :key="`workflow-icon-list-setting-${selectedNode.id}-${index}`" class="workflow-icon-list-setting"><div class="workflow-icon-list-setting__header"><span>{{ t('Item') }} @{{ index + 1 }}</span><div class="workflow-icon-list-setting__actions"><button type="button" class="btn btn-sm btn-link" :disabled="!canWrite || index === 0" @click="moveIconListItem(index, -1)" :aria-label="`Move item ${index + 1} up`"><i class="fas fa-arrow-up" aria-hidden="true"></i></button><button type="button" class="btn btn-sm btn-link" :disabled="!canWrite || index === selectedNode.config.items.length - 1" @click="moveIconListItem(index, 1)" :aria-label="`Move item ${index + 1} down`"><i class="fas fa-arrow-down" aria-hidden="true"></i></button><button type="button" class="btn btn-sm btn-link text-danger" :disabled="!canWrite || selectedNode.config.items.length <= 1" @click="removeIconListItem(index)" :aria-label="`Delete item ${index + 1}`"><i class="fas fa-trash" aria-hidden="true"></i></button></div></div><button type="button" class="workflow-icon-picker-trigger workflow-icon-picker-trigger--compact" :disabled="!canWrite" @click="openIconPicker(selectedNode, index)"><span class="workflow-icon-picker-trigger__preview"><i :class="safeIconClass(item.iconClass, 'fas fa-check')" aria-hidden="true"></i></span><span><strong>@{{ item.iconClass }}</strong><small>{{ t('Choose icon') }}</small></span><i class="fas fa-chevron-right ms-auto" aria-hidden="true"></i></button><label class="form-label mt-2">{{ t('Text') }}<textarea class="form-control" maxlength="500" rows="2" :value="item.text" :readonly="!canWrite" @focus="beginInspectorEdit" @input="item.text = $event.target.value.slice(0, 500); markDirty()"></textarea></label></div></div><button type="button" class="btn btn-sm btn-outline-secondary w-100" :disabled="!canWrite || selectedNode.config.items.length >= 30" @click="addIconListItem(selectedNode)"><i class="fas fa-plus me-1" aria-hidden="true"></i>{{ t('Add item') }}</button><div class="workflow-inspector-grid workflow-inspector-grid--two mt-3"><div><label for="workflow-icon-list-font-size" class="form-label">{{ t('Font size') }}</label><input id="workflow-icon-list-font-size" v-model.number="selectedNode.config.fontSize" class="form-control" type="number" min="10" max="32" step="1" :readonly="!canWrite" @focus="beginInspectorEdit" @input="markDirty"></div><div><label for="workflow-icon-list-gap" class="form-label">{{ t('Gap') }}</label><input id="workflow-icon-list-gap" v-model.number="selectedNode.config.gap" class="form-control" type="number" min="0" max="40" step="1" :readonly="!canWrite" @focus="beginInspectorEdit" @input="markDirty"></div><div><label for="workflow-icon-list-width" class="form-label">{{ t('Width') }}</label><input id="workflow-icon-list-width" v-model.number="selectedNode.config.width" class="form-control" type="number" min="160" max="1000" step="1" :readonly="!canWrite" @focus="beginInspectorEdit" @input="markDirty"></div><div><label for="workflow-icon-list-color" class="form-label">{{ t('Icon color') }}</label><input id="workflow-icon-list-color" v-model="selectedNode.config.color" class="form-control form-control-color w-100" type="color" :disabled="!canWrite" @focus="beginInspectorEdit" @input="markDirty"></div><div class="workflow-inspector-grid__wide"><label for="workflow-icon-list-text-color" class="form-label">{{ t('Text color') }}</label><input id="workflow-icon-list-text-color" v-model="selectedNode.config.textColor" class="form-control form-control-color w-100" type="color" :disabled="!canWrite" @focus="beginInspectorEdit" @input="markDirty"></div></div></div>
                    <div v-if="selectedNode.type === 'trigger'" class="workflow-inspector-section"><h3>{{ t('Trigger settings') }}</h3><label for="workflow-trigger-event" class="form-label">{{ t('Event') }}</label><select id="workflow-trigger-event" v-model="selectedNode.config.event" @change="markDirty" class="form-select" :disabled="!canWrite"><option value="manual">{{ t('Manual') }}</option><option value="form.submitted">{{ t('Form submitted') }}</option><option value="data.created">{{ t('Data created') }}</option><option value="data.updated">{{ t('Data updated') }}</option></select><label for="workflow-trigger-form" class="form-label mt-3">{{ t('Form ID') }} <span class="text-body-secondary">({{ t('optional') }})</span></label><input id="workflow-trigger-form" v-model.trim="selectedNode.config.form_id" @input="markDirty" class="form-control" type="text" :disabled="!canWrite || selectedNode.config.event !== 'form.submitted'"></div>
                    <div v-if="selectedNode.type === 'condition'" class="workflow-inspector-section"><h3>{{ t('Condition settings') }}</h3><label for="workflow-condition-field" class="form-label">{{ t('Field') }}</label><input id="workflow-condition-field" v-model.trim="selectedNode.config.field" @input="markDirty" @focus="beginInspectorEdit" class="form-control" type="text" :readonly="!canWrite"><label for="workflow-condition-operator" class="form-label mt-3">{{ t('Operator') }}</label><select id="workflow-condition-operator" v-model="selectedNode.config.operator" @change="markDirty" class="form-select" :disabled="!canWrite"><option value="eq">equals</option><option value="neq">does not equal</option><option value="gt">greater than</option><option value="gte">greater than or equal</option><option value="lt">less than</option><option value="lte">less than or equal</option><option value="contains">contains</option><option value="exists">exists</option></select><label for="workflow-condition-value" class="form-label mt-3">{{ t('Value') }}</label><input id="workflow-condition-value" v-model.trim="selectedNode.config.value" @input="markDirty" class="form-control" type="text" :disabled="!canWrite || selectedNode.config.operator === 'exists'"></div>
                    <div v-if="selectedNode.type === 'approval'" class="workflow-inspector-section"><h3>{{ t('Approval settings') }}</h3><p class="small text-body-secondary">{{ t('Approval is simulated during a test run and is always marked approved.') }}</p><label for="workflow-approval-user" class="form-label">{{ t('Assignee user ID') }} <span class="text-body-secondary">({{ t('optional') }})</span></label><input id="workflow-approval-user" v-model.number="selectedNode.config.assignee_id" @input="markDirty" class="form-control" type="number" min="1" step="1" :readonly="!canWrite"><label for="workflow-approval-role" class="form-label mt-3">{{ t('Assignee role') }} <span class="text-body-secondary">({{ t('optional') }})</span></label><input id="workflow-approval-role" v-model.trim="selectedNode.config.assignee_role" @input="markDirty" class="form-control" type="text" :readonly="!canWrite"></div>
                    <div v-if="selectedNode.type === 'delay'" class="workflow-inspector-section"><h3>{{ t('Delay settings') }}</h3><label for="workflow-delay-minutes" class="form-label">{{ t('Minutes') }}</label><input id="workflow-delay-minutes" v-model.number="selectedNode.config.minutes" @input="markDirty" class="form-control" type="number" min="0" max="43200" step="1" :readonly="!canWrite"><small class="form-text text-body-secondary">{{ t('Maximum 30 days.') }}</small></div>
                    <div v-if="selectedNode.type === 'email'" class="workflow-inspector-section"><h3>{{ t('Email settings') }}</h3><p class="small text-body-secondary">{{ t('Simulation only. No email will be sent.') }}</p><label for="workflow-email-to" class="form-label">{{ t('To') }}</label><input id="workflow-email-to" v-model.trim="selectedNode.config.to" @input="markDirty" @focus="beginInspectorEdit" class="form-control" type="email" :readonly="!canWrite"><label for="workflow-email-subject" class="form-label mt-3">{{ t('Subject') }}</label><input id="workflow-email-subject" v-model.trim="selectedNode.config.subject" @input="markDirty" class="form-control" type="text" :readonly="!canWrite"></div>
                    <div v-if="selectedNode.type === 'webhook'" class="workflow-inspector-section"><h3>{{ t('Webhook settings') }}</h3><p class="small text-body-secondary">{{ t('Simulation only. No external request will be sent.') }}</p><label for="workflow-webhook-url" class="form-label">{{ t('URL') }}</label><input id="workflow-webhook-url" v-model.trim="selectedNode.config.url" @input="markDirty" @focus="beginInspectorEdit" class="form-control" type="url" placeholder="https://example.test/hook" :readonly="!canWrite"><label for="workflow-webhook-method" class="form-label mt-3">{{ t('Method') }}</label><select id="workflow-webhook-method" v-model="selectedNode.config.method" @change="markDirty" class="form-select" :disabled="!canWrite"><option value="POST">POST</option></select></div>
                    <div v-if="selectedNode.type === 'update'" class="workflow-inspector-section"><h3>{{ t('Update settings') }}</h3><label for="workflow-update-field" class="form-label">{{ t('Field') }}</label><input id="workflow-update-field" v-model.trim="selectedNode.config.field" @input="markDirty" @focus="beginInspectorEdit" class="form-control" type="text" :readonly="!canWrite"><label for="workflow-update-value" class="form-label mt-3">{{ t('Value') }}</label><input id="workflow-update-value" v-model.trim="selectedNode.config.value" @input="markDirty" class="form-control" type="text" :readonly="!canWrite"></div>
                    <div v-if="selectedNode.type === 'end'" class="workflow-inspector-section"><h3>{{ t('End step') }}</h3><p class="small text-body-secondary mb-0">{{ t('This step completes the workflow. It does not have an output port.') }}</p></div>
                    <div class="workflow-inspector__coordinates"><span>{{ t('Position') }}</span><span>@{{ Math.round(selectedNode.x) }}, @{{ Math.round(selectedNode.y) }}</span></div>
                </div>
            </aside>
        </main>

        <dialog v-if="iconPicker.open" ref="iconDialog" class="workflow-icon-dialog" @cancel.prevent="closeIconPicker" @click.self="closeIconPicker">
            <div class="workflow-icon-dialog__panel" role="dialog" aria-modal="true" aria-labelledby="workflow-icon-dialog-title">
                <header class="workflow-icon-dialog__header"><div><span class="workflow-panel-kicker">{{ t('Local library') }}</span><h2 id="workflow-icon-dialog-title" class="h5 mb-0"><i class="fab fa-font-awesome-flag me-2" aria-hidden="true"></i>{{ t('Choose an icon') }}</h2></div><button type="button" class="btn btn-sm btn-outline-secondary" @click="closeIconPicker" aria-label="{{ t('Close') }}"><i class="fas fa-times" aria-hidden="true"></i></button></header>
                <div class="workflow-icon-dialog__body"><aside class="workflow-icon-dialog__groups" aria-label="{{ t('Icon styles') }}"><button v-for="group in iconLibraryGroups" :key="group.key" type="button" class="workflow-icon-dialog__group" :class="{ active: iconPicker.group === group.key }" :aria-pressed="iconPicker.group === group.key" @click="iconPicker.group = group.key; iconPicker.visibleCount = 100"><i :class="group.icon" aria-hidden="true"></i><span>@{{ group.label }}</span></button></aside><section class="workflow-icon-dialog__content"><label class="workflow-icon-dialog__search"><span class="visually-hidden">{{ t('Search icons') }}</span><i class="fas fa-search" aria-hidden="true"></i><input ref="iconSearch" v-model.trim="iconPicker.query" type="search" class="form-control" placeholder="{{ t('Search by name, label, or term') }}" @input="iconPicker.visibleCount = 100"></label><div v-if="iconLibrary.loading" class="workflow-icon-dialog__state"><i class="fas fa-sync-alt fa-spin" aria-hidden="true"></i>{{ t('Loading local icon library') }}...</div><div v-else-if="iconLibrary.error" class="workflow-icon-dialog__state workflow-icon-dialog__state--error" role="alert">@{{ iconLibrary.error }}</div><div v-else-if="!filteredIconLibrary.total" class="workflow-icon-dialog__state">{{ t('No icons match this search') }}.</div><div v-else class="workflow-icon-dialog__grid"><button v-for="item in filteredIconLibrary.items" :key="item.id" type="button" class="workflow-icon-dialog__item" :class="{ active: iconPicker.selected?.id === item.id }" :aria-label="item.label" :aria-pressed="iconPicker.selected?.id === item.id" @click="selectIconPickerItem(item)" @dblclick="selectIconPickerItem(item); applyIconPicker()"><i :class="item.className" aria-hidden="true"></i><span>@{{ item.label }}</span><small>@{{ item.style }}</small></button></div><button v-if="filteredIconLibrary.items.length < filteredIconLibrary.total" type="button" class="btn btn-sm btn-outline-secondary workflow-icon-dialog__load-more" @click="loadMoreIcons">{{ t('Load more') }}</button></section></div>
                <footer class="workflow-icon-dialog__footer"><div v-if="iconPicker.selected" class="workflow-icon-dialog__selected"><i :class="iconPicker.selected.className" aria-hidden="true"></i><span>@{{ iconPicker.selected.label }}</span><small>@{{ iconPicker.selected.style }}</small></div><span v-else class="small text-body-secondary">{{ t('Select an icon from the local library.') }}</span><div class="d-flex gap-2"><button type="button" class="btn btn-sm btn-outline-secondary" @click="closeIconPicker">{{ t('Cancel') }}</button><button type="button" class="btn btn-sm ph-btn-theme" :disabled="!iconPicker.selected" @click="applyIconPicker">{{ t('Use icon') }}</button></div></footer>
            </div>
        </dialog>

        <section id="workflow-simulation" class="ph-content rounded workflow-simulation-panel mt-3" aria-labelledby="workflow-simulation-heading">
            <div class="workflow-simulation-panel__header"><div><span class="workflow-panel-kicker">{{ t('Test') }}</span><h2 id="workflow-simulation-heading" class="h6 mb-1">{{ t('Simulation') }}</h2><p class="small text-body-secondary mb-0">{{ t('Run the saved graph with sample context. Integrations remain simulated.') }}</p><p v-if="!hasExecutableNodes" class="small text-body-secondary mb-0 mt-1"><i class="fas fa-info-circle me-1" aria-hidden="true"></i>{{ t('Add a Trigger to simulate executable steps.') }}</p></div><button type="button" class="btn btn-sm ph-btn-theme" :disabled="!canSimulate" @click="simulate"><span v-if="simulating" class="spinner-border spinner-border-sm me-1" aria-hidden="true"></span><i v-else class="fas fa-play me-1" aria-hidden="true"></i>{{ t('Run simulation') }}</button></div>
            <div class="workflow-simulation-panel__body"><div class="workflow-simulation-context"><label for="workflow-simulation-context" class="form-label">{{ t('Context JSON') }}</label><textarea id="workflow-simulation-context" v-model="simulationContext" class="form-control font-monospace" rows="5" spellcheck="false">{}</textarea><small class="form-text text-body-secondary">{{ t('Example: {"amount": 120, "status": "new"}') }}</small></div><div class="workflow-simulation-result" aria-live="polite"><div v-if="!lastRun" class="workflow-simulation-empty"><i class="fas fa-flask mb-2" aria-hidden="true"></i><span>{{ t('No simulation run yet.') }}</span></div><div v-else><div class="workflow-run-summary"><span class="badge text-bg-success">@{{ lastRun.status }}</span><span class="workflow-run-mode">@{{ lastRun.mode }}</span><span class="small text-body-secondary">@{{ formatDate(lastRun.created_at || lastRun.updated_at) }}</span></div><ul class="workflow-run-logs list-unstyled mb-0"><li v-for="(log, index) in (lastRun.logs || [])" :key="`${log.node_id}-${index}`" :class="`workflow-log--${log.level || 'info'}`"><i class="fas" :class="logIcon(log.level)" aria-hidden="true"></i><span><strong>@{{ log.node_id }}</strong> @{{ log.message }}</span></li></ul></div></div></div>
            <details class="workflow-runs" @toggle="loadRuns"><summary>{{ t('Recent simulation runs') }} <span v-if="runs.length" class="badge text-bg-light ms-1">@{{ runs.length }}</span></summary><div v-if="runsLoading" class="small text-body-secondary p-3">{{ t('Loading runs') }}...</div><div v-else-if="runs.length === 0" class="small text-body-secondary p-3">{{ t('No saved runs') }}</div><div v-else class="table-responsive"><table class="table table-sm mb-0"><thead><tr><th>{{ t('Status') }}</th><th>{{ t('Mode') }}</th><th>{{ t('Logs') }}</th><th>{{ t('Created') }}</th></tr></thead><tbody><tr v-for="run in runs" :key="run.id"><td><span class="badge" :class="run.status === 'completed' ? 'text-bg-success' : 'text-bg-warning'">@{{ run.status }}</span></td><td>@{{ run.mode }}</td><td>@{{ (run.logs || []).length }}</td><td class="text-body-secondary">@{{ formatDate(run.created_at) }}</td></tr></tbody></table></div></details>
        </section>
    </div>
@endsection

